insert into audit.data_sources (source_id, institution, dataset_name, official_title, source_url, source_language, frequency, methodology_notes, is_active) values
  ('BQK_RAPORT_MUJOR', 'BQK', 'Raporti Mujor i Sistemit të Pagesave', 'Monthly Report on Cash and Non-Cash Payment Instruments', 'https://bqk-kos.org/statistikat/?lang=en', 'sq/en', 'monthly', 'Terminal stock and transaction flows come from the same publication, so productivity ratios share a universe. Begins January 2025 and is not continuous with the annual report series.', TRUE),
  ('BQK_T15', 'BQK', 'Table 15 — Payment System', 'Payment System statistical time series, Table 15', 'https://bqk-kos.org/repository/docs/time_series/', 'sq/en', 'monthly', 'Long-run series. Counts published in thousands and values in EUR millions; both are scaled on load. No terminal stock exists on this basis.', TRUE),
  ('BQK_CARDS_ANNUAL', 'BQK', 'Use of Bank Cards in Kosovo', 'Use of Bank Cards in Kosovo — September 2025 edition', 'https://bqk-kos.org/repository/docs/SistemiIPagesave/Use%20of%20bank%20cards%20in%20Kosovo.pdf?lang=en', 'en', 'annual', 'City distribution read from charts, not from a published table. Figures 26 and 27 combine ATM AND POS transactions.', TRUE),
  ('ASK_RETAIL', 'ASK', 'Statistikat afatshkurtra të Tregtisë me Pakicë', 'Short-term retail trade statistics — turnover index, monthly', 'https://askdata.rks-gov.net/', 'sq', 'monthly', 'Turnover index, 2021 = 100. ASK publishes no aggregate retail total in this table, so none is constructed; card growth is compared against each published activity and their unweighted mean.', TRUE),
  ('ASK_ENTERPRISES', 'ASK', 'Regjistri statistikor i bizneseve', 'Statistical business register — registered enterprises', 'https://askdata.rks-gov.net/', 'sq', 'quarterly', 'Registered enterprises by municipality and activity section. A better merchant denominator than ATK taxpayers, which count filers rather than traders — though registration still does not imply trading or card acceptance.', TRUE),
  ('ASK_ACTIVE_ENTERPRISES', 'ASK', 'Statistikat strukturore të bizneseve', 'Structural business statistics — active enterprises by section', 'https://askdata.rks-gov.net/', 'sq', 'annual', 'Enterprises actually trading, by economic section. This is the population a card could be presented to, and the denominator the acceptance question needs. The table carries its own total row, which is used as the total rather than summing the sections on top of it. Annual, and it ends before the BQK merchant series begins.', TRUE),
  ('ASK_ENTERPRISE_SIZE', 'ASK', 'Regjistri statistikor i bizneseve', 'Statistical business register — size of enterprises registered monthly', 'https://askdata.rks-gov.net/', 'sq', 'monthly', 'Employee size class of the enterprises registered in each month, as percentages. A FLOW describing who is registering now, not the size structure of businesses already trading: the micro share moves 98.6% to 99.8% month to month, which a base of fifty thousand could not do.', TRUE),
  ('ASK_ENTERPRISES_CLOSED', 'ASK', 'Regjistri statistikor i bizneseve', 'Statistical business register — enterprises closed, by municipality', 'https://askdata.rks-gov.net/', 'sq', 'quarterly', 'Enterprises closed per quarter, by municipality and activity section. A flow, counted over the same four quarters as the registrations it is subtracted from. A closure is not always a failure.', TRUE),
  ('ASK_TURNOVER_STRUCTURE', 'ASK', 'Statistikat strukturore të bizneseve', 'Structural business statistics — turnover structure by section', 'https://askdata.rks-gov.net/', 'sq', 'annual', 'Share of turnover by economic section, as percentages. Measures the same quantity ATK measures, by a different method and a different institution, so the two can be set against each other rather than one being taken on trust.', TRUE),
  ('DOGANA_IMPORT_2025', 'DOGANA', 'Open Data — Importi 2025', 'Dogana e Kosovës — Open DATA Import 2025', 'https://dogana.rks-gov.net/SharedFolder/DocumentFiles/Open_DATA_Import%20Janar-Dhjetor%202025.xlsx', 'sq', 'monthly', 'Import lines at ten-digit tariff code, by month and country of origin, regime IM4 only. Aggregated to merchant vertical through mapping v1.0. A supply-side signal: goods entered the country, which is not the same as goods sold.', TRUE),
  ('DOGANA_IMPORT_2026', 'DOGANA', 'Open Data — Importi 2026', 'Dogana e Kosovës — Open DATA Import 2026', 'https://dogana.rks-gov.net/SharedFolder/DocumentFiles/Open_DATA_Import%20Janar-Gusht-2026.xlsx', 'sq', 'monthly', 'Import lines at ten-digit tariff code, by month and country of origin, regime IM4 only. Aggregated to merchant vertical through mapping v1.0. A supply-side signal: goods entered the country, which is not the same as goods sold.', TRUE),
  ('ASK_CENSUS', 'ASK', 'Regjistrimi i Popullsisë 2024', 'Population and Housing Census 2024 — first final results', 'https://ask.rks-gov.net/', 'sq', 'annual', 'Population of 1,586,659, used to normalise every absolute figure and to compare with the euro area.', TRUE),
  ('ECB_PAYMENTS', 'ECB', 'Payments statistics', 'ECB, Payments statistics: first half of 2025', 'https://www.ecb.europa.eu/press/stats/paysec/html/ecb.pis2025h1~36edd636c8.en.html', 'en', 'annual', 'Euro-area reference for the same half-year. Figures are quoted from the ECB release as published, never recomputed.', TRUE),
  ('KBA_POS_BY_BANK', 'KBA', 'Bank reporting — POS transactions', 'Shoqata e Bankave të Kosovës — raportimi i bankave për POS', 'https://www.bankassoc-kos.com/', 'sq/en', 'periodic', 'Bank-level POS totals supplied by the project owner as an aggregate extract, not downloaded from a publication. It has no source file to hash and no period label. It is a fourth POS universe: shares and productivity are computed inside it and never divided against a BQK total.', TRUE),
  ('ATK_QARKULLIMI_2019', 'ATK', 'Open Data — Qarkullimi 2019', 'Të dhëna të hapura — Qarkullimi 2019', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2020', 'ATK', 'Open Data — Qarkullimi 2020', 'Të dhëna të hapura — Qarkullimi 2020', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2021', 'ATK', 'Open Data — Qarkullimi 2021', 'Të dhëna të hapura — Qarkullimi 2021', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2022', 'ATK', 'Open Data — Qarkullimi 2022', 'Të dhëna të hapura — Qarkullimi 2022', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2023', 'ATK', 'Open Data — Qarkullimi 2023', 'Të dhëna të hapura — Qarkullimi 2023', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2024', 'ATK', 'Open Data — Qarkullimi 2024', 'Të dhëna të hapura — Qarkullimi 2024', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE),
  ('ATK_QARKULLIMI_2025', 'ATK', 'Open Data — Qarkullimi 2025', 'Të dhëna të hapura — Qarkullimi 2025', 'https://www.atk-ks.org/en/open-data/', 'sq/en', 'monthly', 'Aggregated turnover and REGISTERED TAXPAYER counts by month, municipality, sector and legal form. Taxpayers are not equivalent to card-accepting businesses.', TRUE);
