insert into audit.series_coverage (metric, definition_id, first_period, last_period, expected_observations, actual_observations, missing_observations, coverage_percentage, continuity_status) values
  ('POS transactions (Raport Mujor)', 1, '2025-01', '2026-07', 19, 19, 0, 100.0, 'CONTINUOUS'),
