insert into audit.kpi_build_status (kpi_id, status, reason, required_input) values
  ('pos_terminals', 'PASS', 'Monthly stock available for 19 months; a same-month comparison needs 13.', NULL),
  ('pos_transaction_count', 'PASS', 'Three universes are published and kept separate; the active one is named on every figure.', NULL),
  ('pos_transaction_value', 'PASS', 'Published on the same basis as the count within each definition.', NULL),
  ('transactions_per_average_pos', 'PASS', 'Numerator and denominator come from the same publication and the same universe.', NULL),
  ('transactions_per_end_period_pos', 'WARNING', 'Valid but understates productivity while the network grows; reported alongside the average-stock variant rather than in place of it.', NULL),
  ('value_per_average_pos', 'PASS', 'Same basis on both sides.', NULL),
  ('average_ticket', 'PASS', 'Both sides come from one universe, so the ratio is internally consistent.', NULL),
  ('cards_issued', 'PASS', 'Published monthly as a stock; never summed.', NULL),
  ('pos_per_1000_taxpayers', 'WARNING', 'Numerator is CITY grain and estimated from a PDF chart (1 of 7 legend pairings verified); denominator is MUNICIPALITY grain. Usable as an approximation, stated on the page.', 'BQK POS terminals at municipality grain'),
  ('pos_per_eur1m_addressable', 'WARNING', 'Numerator is CITY grain and estimated from a PDF chart (1 of 7 legend pairings verified); denominator is MUNICIPALITY grain. Usable as an approximation, stated on the page. Denominator is additionally an analytical classification reported as a range.', 'BQK POS terminals at municipality grain; ATK wholesale/retail split'),
  ('turnover_per_taxpayer', 'PASS', 'Both sides from ATK at municipality grain; the denominator is labelled as taxpayers rather than businesses.', NULL),
  ('addressable_turnover', 'WARNING', 'Analytical classification, not an ATK measure. Wholesale and retail are one published sector, so only a floor and a ceiling are defensible.', 'ATK split of wholesale from retail'),
  ('geographic_pos_productivity', 'BLOCKED', 'BQK publishes city transaction figures for ATM and POS combined. A POS-only productivity measure cannot be derived from them.', 'POS-only transaction counts by geography'),
  ('pos_terminal_history_pre_2025', 'BLOCKED', 'The annual and monthly terminal series measure different universes (20,913 at end-2024 against 25,166 in January 2025). They are not spliced.', 'A monthly terminal series on the annual report''s basis'),
  ('transaction_value_bands', 'BLOCKED', 'BQK does not publish card transactions by value band in any reviewed source.', 'Published value-band table'),
  ('bank_pos_share', 'WARNING', 'The extract reconciles exactly to its own published total, so the shares are internally sound. It is marked WARNING for provenance rather than arithmetic: it was supplied as an aggregate rather than downloaded, so it carries no file hash, and BPB and PRB report nothing and are excluded.', 'A hashable KBA publication with a stated period'),
  ('fair_share_index', 'WARNING', 'Numerator and denominator both come from the KBA extract, so the index is internally consistent. It inherits the extract''s missing period label, and it measures value per terminal, not revenue — no public source prices a transaction.', 'A stated reporting period; merchant pricing for any revenue read'),
  ('bank_pos_productivity', 'WARNING', 'Valid within the extract. It must not be read against the BQK per-terminal figures elsewhere in this report, which count a different universe over a known period.', 'A stated reporting period');
